import requests
import unicodedata
from typing import Any, Dict, Union, List, Optional

def get_github_user_normalized(username: str,
                               token: Optional[str] = None,
                               timeout: int = 10) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Parameters:
    - username: GitHub username to look up.
    - token: Optional GitHub personal access token to increase rate limits (string "token" not required).
    - timeout: Request timeout in seconds.

    Returns:
    - A dict with the same structure as the GitHub user JSON, but with all strings normalized to ASCII.

    Raises:
    - requests.RequestException (or subclass) on network/HTTP errors.
    - ValueError if the user is not found (HTTP 404).
    """
    def _normalize_str(s: str) -> str:
        # Normalize Unicode to NFKD and drop non-ASCII characters
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def _normalize(obj: Any) -> Any:
        # Recursively normalize strings within dicts, lists, tuples, and keys
        if isinstance(obj, str):
            return _normalize_str(obj)
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                new_key = _normalize_str(k) if isinstance(k, str) else k
                new[new_key] = _normalize(v)
            return new
        if isinstance(obj, list):
            return [_normalize(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(x) for x in obj)
        # numbers, bool, None, etc. stay unchanged
        return obj

    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    resp.raise_for_status()

    data = resp.json()
    return _normalize(data)

# Example usage:
