def mean_variance(L):
    """
    Compute the mean and variance of all numeric elements in a nested list/tuple/ndarray L.
    Uses numpy for the final computations.
    Returns a tuple (mean, variance).
    Raises ValueError if no numeric elements are found, TypeError if non-numeric values are present.
    """
    import numpy as np

    def _flatten(x):
        # Treat numpy arrays, lists and tuples as containers to recurse into.
        if isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    # If L itself is a scalar (not iterable except strings), handle it by wrapping
    try:
        iter(L)
        flat = list(_flatten(L))
    except TypeError:
        flat = [L]

    if not flat:
        raise ValueError("Input contains no elements")

    # Convert to float array (will raise if conversion fails)
    try:
        arr = np.array(flat, dtype=float)
    except Exception as e:
        raise TypeError("Non-numeric data found in input") from e

    return float(arr.mean()), float(arr.var())

# Example:
# mean, var = mean_variance([[1, 2], [3, [4, 5]]])
